-- Vencimientos CERPAT 2026 — ejecutar UNA vez en la consola SQL de Railway.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
BEGIN;
CREATE TABLE IF NOT EXISTS "configuracion_tributaria" (
  "id" TEXT PRIMARY KEY,
  "organizacionId" TEXT NOT NULL REFERENCES "organizaciones"("id") ON DELETE CASCADE,
  "empresaId" TEXT NOT NULL REFERENCES "empresas"("id") ON DELETE CASCADE,
  "ivaPeriodicidad" TEXT, "retencionFuente" BOOLEAN NOT NULL DEFAULT false,
  "consumoPeriodicidad" TEXT, "rentaTipo" TEXT, "anticipoRstPeriodicidad" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "configuracion_tributaria_empresaId_key" UNIQUE ("empresaId"));
CREATE TABLE IF NOT EXISTS "empresa_municipio_ica" (
  "id" TEXT PRIMARY KEY,
  "organizacionId" TEXT NOT NULL REFERENCES "organizaciones"("id") ON DELETE CASCADE,
  "empresaId" TEXT NOT NULL REFERENCES "empresas"("id") ON DELETE CASCADE,
  "municipioId" TEXT NOT NULL REFERENCES "cat_municipios"("id"),
  "icaPeriodicidad" TEXT, "reteica" BOOLEAN NOT NULL DEFAULT false, "reteicaPeriodicidad" TEXT,
  "autoica" BOOLEAN NOT NULL DEFAULT false, "autoicaPeriodicidad" TEXT,
  CONSTRAINT "empresa_municipio_ica_empresaId_municipioId_key" UNIQUE ("empresaId","municipioId"));
CREATE TABLE IF NOT EXISTS "vencimientos_empresa" (
  "id" TEXT PRIMARY KEY,
  "organizacionId" TEXT NOT NULL REFERENCES "organizaciones"("id") ON DELETE CASCADE,
  "empresaId" TEXT NOT NULL REFERENCES "empresas"("id") ON DELETE CASCADE,
  "anio" INTEGER NOT NULL, "obligacion" TEXT NOT NULL, "periodicidad" TEXT, "periodo" TEXT,
  "municipioId" TEXT REFERENCES "cat_municipios"("id"), "fechaVencimiento" TIMESTAMP(3) NOT NULL,
  "estado" "EstadoPago" NOT NULL DEFAULT 'pendiente', "generado" BOOLEAN NOT NULL DEFAULT true,
  "notas" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);

